INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('38077b88-3b7e-5ac5-8092-b554dfa106cb','TEXT','Proofreading passage PB','The students checked the africanist before the activity began. Our group recorded the africanists in the class notebook. The students checked the africanize before the activity began. Our group recorded the africanized in the class notebook. The students checked the africans before the activity began. Our group recorded the afridi in the class notebook. The students checked the afrikaans before the activity began. Our group recorded the afrikaner in the class notebook. The students checked the afrikanerdom before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
